    "fragSource": "#ifdef GL_FRAGMENT_PRECISION_HIGH\n    precision highp float;\n#else\n    precision mediump float;\n#endif\n\nuniform float uTime;\nuniform float uSpeed;\nuniform float uIntensity;\nuniform float uSeed;\nuniform int uPalette;\nuniform vec2 uResolution;\n\nvec3 palette(float t) {\n    if (uPalette == 1) {\n        return mix(vec3(0.04, 0.0, 0.16), vec3(0.9, 0.18, 1.0), t);\n    }\n    if (uPalette == 2) {\n        return mix(vec3(0.12, 0.02, 0.0), vec3(1.0, 0.55, 0.12), t);\n    }\n    return mix(vec3(0.0, 0.05, 0.12), vec3(0.1, 0.95, 0.9), t);\n}\n\n// Mediump-safe value-noise hash (David Hoskins, \"Hash without sine\").\n// The leading fract() folds large lattice coordinates back into [0, 1]\n// before any multiply, so fbm octaves and time advection stay exact on\n// real-device fragment shaders with reduced precision.\nfloat hash(vec2 p) {\n    vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n    p3 += dot(p3, p3.yzx + 33.33);\n    return fract((p3.x + p3.y) * p3.z);\n}\n\nvoid main(void) {\n    vec2 uv = gl_FragCoord.xy / uResolution.xy;\n    vec2 p = uv * 2.0 - 1.0;\n    p.x *= uResolution.x / uResolution.y;\n\n    float t = uTime * uSpeed + uSeed;\n    float wave1 = sin((p.x * 2.6) + t * 1.2 + sin(p.y * 3.0 + t));\n    float wave2 = sin((p.x * 5.0) - t * 0.7 + cos(p.y * 2.0 - t));\n    float curtain = smoothstep(0.68, 0.0, abs(p.y + wave1 * 0.18 + wave2 * 0.08));\n    float glow = smoothstep(1.2, 0.0, length(p - vec2(0.0, -0.35))) * 0.35;\n    float stars = step(0.996, hash(floor(uv * 120.0)));\n\n    vec3 color = palette(clamp(curtain + glow, 0.0, 1.0));\n    color *= (curtain * uIntensity + glow);\n    color += vec3(stars) * 0.45;\n\n    // Interleaved-gradient-noise dither (~0.75 LSB): hides contour banding\n    // on low-bit-depth device framebuffers. Small constants: mediump-exact.\n    float dith = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));\n    color += (dith - 0.5) * (0.75 / 255.0);\n    gl_FragColor = vec4(color, 1.0);\n}\n",
